-- Modern chandelier offer: 40% off 8 modern styles (average 30 KWD before the sale)
BEGIN;

UPDATE public.categories SET is_active = true WHERE slug = 'chandelier';

CREATE TEMP TABLE chandelier_offer (sku text, slug text, name_en text, name_ar text, base_price numeric, sale_price numeric,
  description_en text, description_ar text, short_en text, short_ar text, image_url text) ON COMMIT DROP;

INSERT INTO chandelier_offer VALUES
('MCH-01', 'modern-geometric-cage-chandelier', 'Modern Geometric Cage Chandelier', 'ثريا حديثة بإطار هندسي', 22.000, 13.250, 'A clean geometric metal frame around a single light source; a light, architectural look for dining areas and entrances. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'إطار معدني هندسي أنيق حول مصدر إضاءة واحد، بمظهر معماري خفيف يناسب غرف الطعام والمداخل. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'A clean geometric metal frame around a single light source; a light, architectural look for dining areas and entrances.', 'إطار معدني هندسي أنيق حول مصدر إضاءة واحد، بمظهر معماري خفيف يناسب غرف الطعام والمداخل.', 'https://images.unsplash.com/photo-1605102393474-e60aaa90445c?auto=format&fit=crop&q=80&w=800'),
('MCH-02', 'modern-cone-pendant-cluster-chandelier', 'Modern Cone Pendant Cluster Chandelier', 'ثريا حديثة عناقيد مخروطية', 25.000, 15.000, 'A cluster of cone shades hung at staggered heights, casting focused light over dining tables and kitchen islands. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'مجموعة من الأغطية المخروطية معلّقة على ارتفاعات متدرجة تمنح إضاءة مركّزة فوق طاولات الطعام وجزر المطبخ. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'A cluster of cone shades hung at staggered heights, casting focused light over dining tables and kitchen islands.', 'مجموعة من الأغطية المخروطية معلّقة على ارتفاعات متدرجة تمنح إضاءة مركّزة فوق طاولات الطعام وجزر المطبخ.', 'https://images.unsplash.com/photo-1669060353074-10afdc617ede?auto=format&fit=crop&q=80&w=800'),
('MCH-03', 'modern-wire-sphere-cluster-chandelier', 'Modern Wire Sphere Cluster Chandelier', 'ثريا حديثة كرات سلكية', 27.000, 16.250, 'Open wire spheres arranged in a vertical cluster; suits double-height halls and stairwells. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'كرات سلكية مفتوحة مرتبة في عنقود عمودي، مناسبة للصالات المرتفعة وبيت الدرج. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'Open wire spheres arranged in a vertical cluster; suits double-height halls and stairwells.', 'كرات سلكية مفتوحة مرتبة في عنقود عمودي، مناسبة للصالات المرتفعة وبيت الدرج.', 'https://images.unsplash.com/photo-1584282114082-b21c8af7a19c?auto=format&fit=crop&q=80&w=800'),
('MCH-04', 'modern-glass-bubble-chandelier', 'Modern Glass Bubble Chandelier', 'ثريا حديثة فقاعات زجاجية', 29.000, 17.500, 'Clear glass bubbles suspended on fine cables for a sparkling, contemporary centrepiece. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'فقاعات زجاجية شفافة معلّقة على أسلاك رفيعة لقطعة مركزية عصرية لامعة. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'Clear glass bubbles suspended on fine cables for a sparkling, contemporary centrepiece.', 'فقاعات زجاجية شفافة معلّقة على أسلاك رفيعة لقطعة مركزية عصرية لامعة.', 'https://images.unsplash.com/photo-1598155038124-0ae4d7300461?auto=format&fit=crop&q=80&w=800'),
('MCH-05', 'modern-sputnik-globe-chandelier', 'Modern Sputnik Globe Chandelier', 'ثريا سبوتنيك حديثة بكرات', 31.000, 18.500, 'Mid-century inspired sputnik arms finished with opal glass globes; a statement piece for living rooms. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'أذرع سبوتنيك مستوحاة من تصاميم منتصف القرن مع كرات زجاج أوبال، قطعة لافتة لغرف المعيشة. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'Mid-century inspired sputnik arms finished with opal glass globes; a statement piece for living rooms.', 'أذرع سبوتنيك مستوحاة من تصاميم منتصف القرن مع كرات زجاج أوبال، قطعة لافتة لغرف المعيشة.', 'https://images.unsplash.com/photo-1561312578-327c29b5b7e3?auto=format&fit=crop&q=80&w=800'),
('MCH-06', 'modern-crystal-rain-chandelier', 'Modern Crystal Rain Chandelier', 'ثريا كريستال حديثة على شكل مطر', 33.000, 19.750, 'Strands of crystal drops falling like rain; a modern take on the crystal chandelier for majlis and reception areas. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'خيوط من قطرات الكريستال تتساقط كالمطر، رؤية عصرية للثريا الكريستال تناسب المجالس وصالات الاستقبال. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'Strands of crystal drops falling like rain; a modern take on the crystal chandelier for majlis and reception areas.', 'خيوط من قطرات الكريستال تتساقط كالمطر، رؤية عصرية للثريا الكريستال تناسب المجالس وصالات الاستقبال.', 'https://images.unsplash.com/photo-1679108230530-325f77243adc?auto=format&fit=crop&q=80&w=800'),
('MCH-07', 'modern-double-ring-led-chandelier', 'Modern Double Ring LED Chandelier', 'ثريا LED حديثة بحلقتين', 35.000, 21.000, 'Two interlocking LED rings giving a soft, even glow; minimal and modern. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'حلقتان LED متداخلتان تمنحان توهجاً ناعماً ومتساوياً بتصميم بسيط وعصري. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'Two interlocking LED rings giving a soft, even glow; minimal and modern.', 'حلقتان LED متداخلتان تمنحان توهجاً ناعماً ومتساوياً بتصميم بسيط وعصري.', 'https://images.unsplash.com/photo-1773813956695-1279f2a5b2ae?auto=format&fit=crop&q=80&w=800'),
('MCH-08', 'modern-multi-ring-led-chandelier', 'Modern Multi-Ring LED Chandelier', 'ثريا LED حديثة متعددة الحلقات', 38.000, 22.750, 'Glowing LED rings hung at different heights; designed for stairwells and high ceilings. Available at our showroom in Hawalli with delivery across Kuwait; ask us on WhatsApp for sizes and finishes.', 'حلقات LED مضيئة معلّقة على ارتفاعات مختلفة، مصممة لبيت الدرج والأسقف المرتفعة. متوفرة في معرضنا في حولي مع التوصيل لجميع مناطق الكويت؛ تواصل معنا عبر واتساب للمقاسات والألوان.', 'Glowing LED rings hung at different heights; designed for stairwells and high ceilings.', 'حلقات LED مضيئة معلّقة على ارتفاعات مختلفة، مصممة لبيت الدرج والأسقف المرتفعة.', 'https://images.unsplash.com/photo-1790090820375-b08c2f0020bd?auto=format&fit=crop&q=80&w=800');

INSERT INTO public.products (sku, slug, name_en, name_ar, base_price, sale_price, category_id, description_en, description_ar,
  short_description_en, short_description_ar, stock_quantity, low_stock_threshold, is_active, is_bestseller, is_featured, is_new)
SELECT o.sku, o.slug, o.name_en, o.name_ar, o.base_price, o.sale_price, c.id, o.description_en, o.description_ar,
  o.short_en, o.short_ar, 9999, 0, true, false, true, true
FROM chandelier_offer o JOIN public.categories c ON c.slug = 'chandelier'
WHERE NOT EXISTS (SELECT 1 FROM public.products p WHERE p.sku = o.sku);

UPDATE public.products p
SET base_price = o.base_price, sale_price = o.sale_price, is_active = true
FROM chandelier_offer o WHERE p.sku = o.sku;

INSERT INTO public.product_images (product_id, url, is_primary, sort_order, alt_text_en, alt_text_ar)
SELECT p.id, o.image_url, true, 0, o.name_en, o.name_ar
FROM chandelier_offer o JOIN public.products p ON p.sku = o.sku
WHERE NOT EXISTS (SELECT 1 FROM public.product_images pi WHERE pi.product_id = p.id);

COMMIT;
